STAFF_FACES = ("front", "back", "left", "right", "top", "bottom")


def staff_art_check(m, model_bytes, tex, icon, vmodel):
    """the 0.1.5 shape rules for one staff: JSON round trip, the vanilla rig kept, 6 faces per box all inside the texture, sizes"""
    md = json.loads(model_bytes.decode("utf-8"))
    assert (json.dumps(md, indent=2) + "\n").encode("utf-8") == model_bytes, m + ": model JSON round trip"
    tw, th = SA.png_size(tex)
    assert tw % 32 == 0 and th % 32 == 0, "%s texture %dx%d is not a multiple of 32" % (m, tw, th)
    assert SA.png_size(icon) == (64, 64), "%s icon %s" % (m, SA.png_size(icon))
    for _rn in RIG_NODES:
        _a, _b = MS.find(md["nodes"], _rn), MS.find(vmodel["nodes"], _rn)
        assert _a is not None and _b is not None and _a.get("position") == _b.get("position") and _a.get("orientation") == _b.get("orientation"), \
            "%s: rig node %s moved off the vanilla staff's" % (m, _rn)
    _boxes = MS.all_boxes(md["nodes"], [])
    _faces = SA.model_faces(md)
    assert len(_boxes) >= 20 and len(_faces) == 6 * len(_boxes), "%s: %d boxes, %d faces" % (m, len(_boxes), len(_faces))
    for _f in _faces:
        _w, _h = _f["wh"]
        _pts = [SA.uv_point(_f["layout"], u, v) for u, v in ((0, 0), (_w, 0), (_w, _h), (0, _h))]
        assert min(p[0] for p in _pts) >= -1e-6 and min(p[1] for p in _pts) >= -1e-6 and max(p[0] for p in _pts) <= tw + 1e-6 \
            and max(p[1] for p in _pts) <= th + 1e-6, "%s: face %s.%s leaves its %dx%d texture: %s" % (m, _f["node"], _f["face"], tw, th, _pts)
    return len(_boxes), (tw, th)


