def pcfg_resolved(pid):
    d = az_json(az_path("pcfg", pid))
    if not d.get("Parent"):
        return json.loads(json.dumps(d))
    b = pcfg_resolved(d["Parent"])
    b.update(dict((k, json.loads(json.dumps(v))) for k, v in d.items() if k != "Parent"))
    return b


