# fighter rule), B = 30 % of it rounded to 5, the staff's damage per Mana = STAFF_BASE x mult / C (charged), per-target = 0.40 x that x B


def mage_pool(l):
    return 30 + 10 * l + 0.2 * (l // 9)


def round5(x):
    return int(5 * math.floor(x / 5.0 + 0.5 + 1e-9))


