    BOOK[_m] = dict(pool=_pool, cost=_b, dpm=_dpm, dmg=rhu(BOOK_KDEF * _dpm * _b))
    assert _b <= 0.40 * _pool and abs(BOOK[_m]["dmg"] / (_dpm * _b) - BOOK_KDEF) < 0.01, (_m, BOOK[_m])
