# ---- TravWorld.run: once per world tick (TravTick) - effects, quick orb ranges, record hygiene
M(tworld, r"""
public void run(@ST@ st, @CB@ buf, long now) {
  for (int k = this.fx.size() - 1; k >= 0; k--) {
    @PKG@.TravFx f = (@PKG@.TravFx) this.fx.get(k);
    if (now >= f.until) {
      this.fx.remove(k);
      @PKG@.ArmoryTrav.endFx(f, buf);
      continue;
    }
    if (f.kind != 0 && now >= f.next) {
      f.next = f.next + f.step;
      if (f.next <= now) f.next = now + f.step;
      try { @PKG@.ArmoryTrav.tickFx(f, st, buf, now); } catch (Throwable t1) { @PKG@.ArmoryTrav.warn("tickfx", "a traversal tick failed (" + t1 + ")"); }
    }
    if (f.kind != 0 && now >= f.fxNext && @PKG@.TravMath.emitOk(now, f.kind == 1 ? @PKG@.ArmoryTrav.EMIT_TRAIL_MS : @PKG@.ArmoryTrav.EMIT_RING_MS, f.until)) {
      f.fxNext = now + (f.kind == 1 ? @PKG@.ArmoryTrav.EMIT_TRAIL_MS : @PKG@.ArmoryTrav.EMIT_RING_MS);      // 0.1.3: = the systems' LifeSpan
      @PKG@.ArmoryTrav.drawFx(f, buf);
    }
  }
  java.util.Iterator it = this.quick.entrySet().iterator();
  while (it.hasNext()) {
    java.util.Map.Entry e = (java.util.Map.Entry) it.next();
    @REF@ r = (@REF@) e.getKey();
    @PKG@.TravShot s = (@PKG@.TravShot) e.getValue();
    if (r == null || !r.isValid()) { it.remove(); continue; }
    @VEC@ p = @PKG@.ArmoryTrav.posOf(buf, r);
    if (p == null) continue;
    double dx = p.x - s.sx;
    double dy = p.y - s.sy;
    double dz = p.z - s.sz;
    if (dx * dx + dy * dy + dz * dz > s.range * s.range) {
      it.remove();
      try { buf.removeEntity(r, @REMR@.REMOVE); @PKG@.ArmoryTrav.RANGED = @PKG@.ArmoryTrav.RANGED + 1L; } catch (Throwable t2) { }
    }
  }
  java.util.Iterator ib = this.books.entrySet().iterator();          // 0.1.6: a Page Burst orb past book.range bursts there
  while (ib.hasNext()) {
    java.util.Map.Entry eb = (java.util.Map.Entry) ib.next();
    @REF@ rb = (@REF@) eb.getKey();
    @PKG@.TravShot sb = (@PKG@.TravShot) eb.getValue();
    if (rb == null || !rb.isValid()) { ib.remove(); continue; }
    @VEC@ pb = @PKG@.ArmoryTrav.posOf(buf, rb);
    if (pb == null) continue;
    double bx = pb.x - sb.sx;
    double by = pb.y - sb.sy;
    double bz = pb.z - sb.sz;
    if (bx * bx + by * by + bz * bz > sb.range * sb.range) {
      ib.remove();
      try { buf.removeEntity(rb, @REMR@.REMOVE); @PKG@.ArmoryTrav.BOOK_RANGED = @PKG@.ArmoryTrav.BOOK_RANGED + 1L; } catch (Throwable tb) { }
    }
  }
  java.util.Iterator io = this.orbs.keySet().iterator();
  while (io.hasNext()) { @REF@ r = (@REF@) io.next(); if (r == null || !r.isValid()) io.remove(); }
  if (this.pend.size() > 256) this.pend.clear();
}""")


